\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >A<lexander gestabat lapidem in subligari purpureo}}\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 qui Pirofilus dicitur. Hic lapis miram habet potenciam. ... Cumque Alexander redisset ab India et Eufratem fluuium transisset ... - ... rubei habens candorem admixtum.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Bei Satzumstellung weitgehend \u252 \'fcbereinstimmend mit \plain \f1\scaps\lang1033\fs24 Thomas Cantimpratensis\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De rerum natura, lib. XIV}}\plain \f1\lang1033\fs24  (De lapidibus), cap. LVI (De Pyrophilo), vgl. H. \plain \f1\scaps\lang1033\fs24 Boese\plain \f1\lang1033\fs24  (Hg.), Thomas Cantimpratensis: Liber de natura rerum, Editio princeps secundum codices manuscriptos, Teil 1: Text, Berlin, New York 1973, S. 367. }

