\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (6-8) (29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De 12 urbibus ab Alexandro conditis}}\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 (Exzerpte aus {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Petrus Comestor}}\plain \f1\lang1033\fs24 ,\plain \f1\b\lang1033\fs24  \plain \f1\lang1033\fs24 Additamentum 5 zu {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ekkehardus Uraugensis}}\plain \f1\lang1033\fs24  und {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Marcus Junianus Justinus}}\plain \f1\scaps\lang1033\fs24 )\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (6) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >V<ixit autem Alexander annis xxxiii mense uno}}\plain \f1\i\lang1033\fs24 , imperio potitus \plain \f1\lang1033\fs24 (?)\plain \f1\i\lang1033\fs24  annos xii condiditque urbes xii quas omnes de suo nomine Alexandrias nuncupauit \plain \f1\lang1033\fs24 (7) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Aufz\u228 \'e4hlung der St\u228 \'e4dtegr\u252 \'fcndungen Alexanders:\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Alexandria qua condita est sub nomine Bucefali equi}}\plain \f1\i\lang1033\fs24 , Alexandria montuosa ... Insigniuit ergo earum muros primorum quinque grecorum elementis uti legitur in eis \u8218 \'82Alexander rex genus \plain \f1\lang1033\fs24 (30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f3\i\lang1032\fs24 Iouis fecit\rquote : \u913 \'c1 \u914 \'c2 \u915 \'c3 \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 es fehlt: \plain \f3\i\lang1032\fs24 \u916 \'c4\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  \plain \f3\i\lang1032\fs24 \u919 \'c7 ... - ... vino et veneno superatus atque extinctus occubuit. \plain \f1\lang1033\fs24 (8) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Erat enim vir sapientia humana potencia magnitudine animi preditus}}\plain \f1\i\lang1033\fs24 . Qui ex quo imperium suscepit tantam fiduciam suis militibus fecit ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... non uirtute hostili, sed insidiis suorum et fraude civili.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (6) weitgehend \u252 \'fcbereinstimmend mit \plain \f1\scaps\lang1033\fs24 Petrus Comestor\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Historia scholastica}}\plain \f1\lang1033\fs24 , Historia libri Esther, cap. V, vgl. Druck: PL 198, Sp. 1498C; (7) Additamentum 5 zu \plain \f1\scaps\lang1033\fs24 Ekkehardus Uraugiensis\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chronicon universale}}\plain \f1\lang1033\fs24 , vgl. MGH SS VI (s. o. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), S. 75; (8) weitgehend \u252 \'fcbereinstimmend mit \plain \f1\scaps\lang1033\fs24 Marcus Junianus Justinus\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epitoma historiarum Philippicarum Pompei Trogi}}\plain \f1\lang1033\fs24 , lib. 12, cap. 16, vgl. O. \plain \f1\scaps\lang1033\fs24 Seel\plain \f1\lang1033\fs24  (Hg.) Epitoma historiarum Philippicarum Pompei Trogi, 1985, S. 120f.}

