\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  [Nachtrag, wohl von H 3, s. o. Geschichte sowie Einleitung, Abb. 17:] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Cedula pro gradu baccalaureatus eines Studenten der Erfurter Universit\u228 \'e4t mit Verzeichnis der besuchten Vorlesungen und \u220 \'dcbungen}}\plain \f1\b\lang1033\fs24 , 1444\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item sum intitulatus sub rectoratu}}\plain \f1\i\lang1033\fs24  venerabilis viri domini doctoris Heynrici de Bottelstete. Item audiui secundam partem Alexandri a uenerabili uiro magistro Johanne Collede ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... Item exercicium de anima a magistro Heynrico de Runne.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Unter den 135 Studenten, die sich w\u228 \'e4hrend des Rektorats des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Heinrich Buttelstedt von Wei\u223 \'dfensee}}\plain \f1\lang1033\fs24  (Wahl zum Rektor: 1. Mai 1440) einschrieben (vgl. \plain \f1\scaps\lang1033\fs24 Weissenborn\plain \f1\lang1033\fs24  I, S. 179f.), auch {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Pueri (Kindt) de Frankenhusen}}\plain \f1\lang1033\fs24 , s. o. Geschichte; zu Heinrich Buttelstedt vgl. auch \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 333f., Nr. 20 u. \u246 \'f6.; \plain \f1\scaps\lang1033\fs24 Schwinges/Wriedt\plain \f1\lang1033\fs24 , S. 31, Nr. 54.3; \plain \f1\scaps\lang1033\fs24 Gramsch\plain \f1\lang1033\fs24 , Erfurter Juristen, S. 177 u. \u246 \'f6. sowie PK Nr. 107, \plain \f1\scaps\lang1033\fs24 Stewing\plain \f1\lang1033\fs24 , LB, Nr. 188. Die Zeit zwischen Studienbeginn und Bakkalaureatsexamen betrug mindestens drei, aber \u8222 \'84fast regelm\u228 \'e4\u223 \'dfig vier bis sechs Semester\ldblquote  (\plain \f1\scaps\lang1033\fs24 Schwinges/Wriedt\plain \f1\lang1033\fs24 , S. XXIV); Johannes Pueri legte die Bakkalarspr\u252 \'fcfung erst im Herbst 1444 ab, s. o. Geschichte.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Im Einzelnen werden die folgenden 19 Lehrveranstaltungen und 18 Lehrenden genannt: 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 I. Grammatik: 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (a)\plain \f1\i\lang1033\fs24  secundam partem {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Alexandri}}{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  [de Villadei}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Doctrinale}}\plain \f1\lang1033\fs24 ] bei (1) \plain \f1\i\lang1033\fs24 mgr. Johannes Collede\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Kollede}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 339f. u. \u246 \'f6.; Stewing, LB, Nr. 193); (b) {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Priscianum}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Institutiones grammaticae}}\plain \f1\lang1033\fs24 ] bei (2) \plain \f1\i\lang1033\fs24 mgr. Johannes de Ammelborgen\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Amelborg}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 413, Nr. 122 u. \u246 \'f6.); (c) {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Donatum}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 bei (3) \plain \f1\i\lang1033\fs24 mgr. Johannes de Goch\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[7].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes de Goch}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Schwinges/Wriedt\plain \f1\lang1033\fs24 , S. 37, Nr. 63.3; \plain \f1\scaps\lang1033\fs24 Stewing\plain \f1\lang1033\fs24 , LB, Nr. 77; nicht identisch mit Johannes [Mosa] de Goch [1395 imm.], vgl. \plain \f1\scaps\lang1033\fs24 Weissenborn\plain \f1\lang1033\fs24  I, S. 45\plain \f1\super\lang1033\fs24 32\plain \f1\lang1033\fs24 ; \plain \f1\scaps\lang1033\fs24 Gramsch\plain \f1\lang1033\fs24 , Erfurter Juristen, S. 686 und PK Nr. 212; \plain \f1\scaps\lang1033\fs24 Stewing\plain \f1\lang1033\fs24 , LB, Nr. 280); 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 II. Logik: 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (d) {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 parua loycalia}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 bei (4) \plain \f1\i\lang1033\fs24 mgr. Johannes Swarcze de Zusato\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[8].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Swarte de Sosato}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 426); (e) {\field{\*\fldinst HYPERLINK "hida://bezper[9].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Petrus Hispanus}}\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Summulae logicales}}\plain \f1\lang1033\fs24 ] bei (5) \plain \f1\i\lang1033\fs24 mgr. Petrus Merle\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[10].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Petrus Henbeck de Merle}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 421, Nr. 193; II, S. 319f.; \plain \f1\scaps\lang1033\fs24 Schwinges/Wriedt\plain \f1\lang1033\fs24 , S. 43, Nr. 72.7; \plain \f1\scaps\lang1033\fs24 Stewing\plain \f1\lang1033\fs24 , LB, Nr. 283); (f) \plain \f1\i\lang1033\fs24 vetus ars\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Praedicamenta, Perihermenias, Isagoge}}\plain \f1\lang1033\fs24 ] bei (6) \plain \f1\i\lang1033\fs24 mgr. Jacobus de Salueldia\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[11].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jakob Reinhold de Salveldia}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 408, Nr. 75 u. \u246 \'f6.; \plain \f1\scaps\lang1033\fs24 Schwinges/Wriedt\plain \f1\lang1033\fs24 , S. 16, Nr. 32.22; \plain \f1\scaps\lang1033\fs24 Stewing,\plain \f1\lang1033\fs24  LB, Nr. 296); (g) {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 priorum }}{\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [analytica priora]}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 bei (7) \plain \f1\i\lang1033\fs24 mgr. Hugo Forster\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[12].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hugo Forster Erffordensis}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 396, 425, Nr. 242; \plain \f1\scaps\lang1033\fs24 Schwinges/Wriedt\plain \f1\lang1033\fs24 , S. 51, Nr. 83.7; \plain \f1\scaps\lang1033\fs24 Gramsch\plain \f1\lang1033\fs24 , Erfurter Juristen, S. 686 und PK Nr. 186); (h) {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 posteriorum }}{\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [analytica posteriora]}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 bei (8) \plain \f1\i\lang1033\fs24 mgr. Rulen\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[13].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Rule de Dorpat}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Kleineidam\plain \f1\lang1033\fs24  I, S. 464; \plain \f1\scaps\lang1033\fs24 Gramsch\plain \f1\lang1033\fs24 , Erfurter Juristen, S. 237 und PK Nr. 515); (i) \plain \f1\i\lang1033\fs24 elencorum\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[8].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De sophisticis elenchis}}\plain \f1\lang1033\fs24 ] bei (9) \plain \f1\i\lang1033\fs24 mgr. Michahel Dommeyer\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[14