\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -48\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Joachim de Flore}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Concordia veteris ac novi testamenti}}\plain \f1\lang1033\fs24 , Ausz\u252 \'fcge.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) [Praefatio, ohne Schlu\u223 \'df und Kap.verzeichnis:] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >Q<uia labentis ac perituri seculi perurgere ruinam}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  - \plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 pro talibus laboris onus inscribendo subire? Sed hec omnia etc.\plain \f1\lang1033\fs24 ; (2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -11\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) [Ausz\u252 \'fcge aus I,1; I,11f.; II/1,5; II/2,11f.; III/1,1; III/2,5-7:] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >N<on habentibus in hoc mundo manentem hereditatem}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ut sequatur sabbatum requietionis\plain \f1\lang1033\fs24 ; (11\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -16\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) [Ausz\u252 \'fcge aus IV/1,1; IV/1,30-46; IV/2,1f.] {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >P<ost initia primi libri qui in fundamento huius operis}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... supra quam credi potest uiuersa uastabit\plain \f1\lang1033\fs24 ;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (16\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -29\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) [Ausz\u252 \'fcge aus V,18-30; V,34-92; V,94-108] {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >S<exto die dixit deus ut produceret terra}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  - \plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 plurimam concordiam cum apocalypsis Iohannis\plain \f1\lang1033\fs24 ; (30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) leer; (32\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -40\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) [Einschub, s. u.:];\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Rest der Seite und 40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  [ohne Seiteneinrichtung]) leer. (41\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -48\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) [Ausz\u252 \'fcge aus V,109-118:]{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  >D<aniel propheta qui apud hebreos inter agyographa computatur}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 deus clariora adhuc facere misteria sua\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24 Explicit concordia\plain \f1\lang1033\fs24  <. 
\par \pard\keep\keepn\fi0\li0\qj\ri0\sb0\sa0\itap0 5\plain \f1\super\lang1033\fs24 r-v \plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tabelle mit Generationen von Adam bis Christus}}\plain \f1\lang1033\fs24 . Lib. V. vom Druck abweichende Einteilung in Distinctiones. Marginale Korrekturen und Nachtr\u228 \'e4ge von sp\u228 \'e4terem Schreiber, u. a. 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : zu V,45.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Druck: Joachim de Flore, Concordia Novi ac Veteris Testamenti, Venedig 1519, 2\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -135\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  (ND: Frankfurt \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 1964, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 1983); die B\u252 \'fccher I-IV auch ediert in: E. R. \plain \f1\scaps\lang1033\fs24 Daniel\plain \f1\lang1033\fs24  (Hg.), Abbot Joachim of Fiore, Liber de concordia novi ac veteris testamenti, Philadelphia 1983 (Transactions of the American Philosophical Society 73,8). Zur \u220 \'dcberlieferung (jeweils ohne diese Hs.) vgl. \plain \f1\scaps\lang1033\fs24 Stegm\plain \f1\scaps\lang1033\fs24 \u252 \'fc\plain \f1\scaps\lang1033\fs24 ller,\plain \f1\lang1033\fs24  RB III, Nr. 4010; \plain \f1\scaps\lang1033\fs24 Reeves\plain \f1\lang1033\fs24 , Influence of Prophecy, Nr. 1, S. 512. Dieselbe Exzerptsammlung auch in \plain \f1\i\lang1033\fs24 Mi\plain \f1\lang1033\fs24 , 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -37\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  (s. o. Geschichte). }

