\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ps.-Sophronius Eusebius Hieronymus}}\plain \f1\lang1033\fs24 : Prologus in epistolas canonicas. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Non est ita [sonst: ordo] apud Grecos qui integre sapiunt}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... vel etiam visibiliter irruens procellat. \plain \f1\lang1033\fs24 (172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -180\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Iac\plain \f1\lang1033\fs24 , Glossa: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iacobus cognomento [sonst: iustus] tercius filius Marie sororis matris domini}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... per hoc ampliora gaudia vite celestis sibi conquirit.\plain \f1\lang1033\fs24  (180\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 I Pt\plain \f1\lang1033\fs24 , Glossa: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Aduene latine grece proseliti [durch Unterpunktung korr. aus: proselitii]. Sic appellabant iudei}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... et a pressura diaboli non potest esse immunis.\plain \f1\lang1033\fs24  (188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -193\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 II Pt\plain \f1\lang1033\fs24 , Glossa: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Istam eisdem quibus et primam scribit epistolam}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... Vnde ad suam ipsorum perditionem est. \plain \f1\lang1033\fs24 (193\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -201\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 I Io\plain \f1\lang1033\fs24 , Glossa: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Scripserat Iohannes evangelium aduersus dogmata hereticorum}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... qui etiam mundum deo praeponunt idolatre sunt. \plain \f1\lang1033\fs24 (201\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 II Io\plain \f1\lang1033\fs24 , Glossa: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum quidam dubitent utrum he due epistole}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... ita contra electos ex persona electorum salutat. \plain \f1\lang1033\fs24 (202\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -203\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 III Io\plain \f1\lang1033\fs24 , Glossa: {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gaius fide Christi suscepta bonis in actibus}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... ut veritatis inimicos a salute monstrat extraneos. \plain \f1\lang1033\fs24 (203\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -205\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Iud\plain \f1\lang1033\fs24 , Glossa: {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iudas qui et Tadeus contra eosdem fidei corruptores}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... quam uolentibus et potens cui nil resistit.\plain \f1\lang1033\fs24  Text und Kommentar in Drei-Spalten-Grundform angelegt, vgl. \plain \f1\scaps\lang1033\fs24 Powitz,\plain \f1\lang1033\fs24  Codices manuscripti 5, Nr. 2. 
