\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Brauner Kalbsledereinband}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Ende 15. / Anfang 16. Jh.}}\plain \f1\lang1033\fs20 , franz\u246 \'f6sischer Dekorationstyp (Vergleichsbeispiele in: Reliures m\u233 \'e9di\u233 \'e9vales 1-3), mit Streich\-eisenlinien und Einzel\-stempeln: Hirsch (rechteckig umrandet, nach links, H\u246 \'f6he ca. 0,9 cm.), Lamm (rechteckig umrandet, nach rechts, H\u246 \'f6he ca. 0,9 cm.), Ranke (rechteckig umrahmt, S-f\u246 \'f6rmig, H\u246 \'f6he ca. 1,1 cm.), Viereck (rechteckig, gekreuzt, H\u246 \'f6he ca. 0,8 cm.); Langriemenschlie\u223 \'dfe am VD (Reste des Lederriemens sichtbar) und Dorn am HD fehlen; der R\u252 \'fccken erneuert; auf dem R\u252 \'fccken Titel- und Signaturschild der Weimarer Bibliothek.}

