\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Pius Papa, II.}}\plain \f1\b\lang1033\fs24  (Aeneas Silvius Piccolomini): {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola ad Christopherum Mauro ducem Venetiarum}}\plain \f1\lang1033\fs24 .
\par \pard\keep\keepn\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Epistola Pii secundi pontificis maximi ad Christofforum Mauro ducem Venetiarium. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pius episcopus seruus seruorum dei nobili viro Christofforo Mauro duci Veneciarum salutem}}\plain \f1\i\lang1033\fs24  et apostolicam benedictionem. Quoniam pridem occulto contepimus animo ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... voluntatem nostram celesti beneplacito subicientibus. Datum Rome aput sanctum Petrum. 
\par \pard\keep\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Der Brief entstand wohl im Zusammenhang mit den seit 1463 anhaltenden Bestrebungen Pius\rquote  II., Venedig, Ungarn und Albanien in die antit\u252 \'fcrkische Koalition gegen Sultan Mohammed II. einzubinden. Zum 79. venezianischen Dogen Cristoforo Moro (reg. 1462-1471) vgl. A. \plain \f1\scaps\lang1033\fs24 Aric\plain \f1\scaps\lang1033\fs24 \u243 \'f3\plain \f1\lang1033\fs24 , / Ch. \plain \f1\scaps\lang1033\fs24 Frison\plain \f1\lang1033\fs24  (Hg.), Marin Sanduno il Giovane, Le vite dei dogi 1423-1474, Venedig 2004, Bd. II, S. 32-153, v. a. S. 35 mit Anm. 103. Ein weiterer Brief Pius\rquote  II. an Cristoforo Moro (12.3.1462) u. a. in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 M\u252 \'fcnchen, SB, Cgm 975, 273}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r-v}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Schneider,\plain \f1\lang1033\fs24  BSB M\u252 \'fcnchen V,6, S. 35, mit weiterer Lit.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset2 Symbol;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Antonius Piccolomini}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola ad Adrianum et Thadeum fratres religiosos}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Anthonius Picclomeus (!) salutem plurimam dicit Adriano et Thadeo fratribus religiosis}}\plain \f1\i\lang1033\fs24 . Numquam adeo putaui vos veros monachos ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... molestior esse silencium quo mecum vtimini. Valete.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bamberg, StB, Msc. Patr. 81, 203}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f1\lang1033\fs24  und {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Msc. Class. 93, 215}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Leitschuh\plain \f1\lang1033\fs24 , Bamberg I/1, S. 455; I/2, S. 113.}

