\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (135\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) [H]\plain \f1\i\lang1033\fs24 oc decretum quod sequitur invenitur I q vii \lquote quociens\rquote  \plain \f1\lang1033\fs24 [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Decretum Gratiani}}\plain \f1\lang1033\fs24 , pars II, causa I, quaest. 7, cap. 9:] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quociens cordis oculus nube erroris obductus}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... presentibus \plain \f1\lang1033\fs24 \u183 \'b7\plain \f1\i\lang1033\fs24 B\plain \f1\lang1033\fs24 \u183 \'b7\plain \f1\i\lang1033\fs24  Bartholomeum\plain \f1\lang1033\fs24  [!]\plain \f1\i\lang1033\fs24  episcopo \plain \f1\lang1033\fs24 [korrigiert aus - \plain \f1\i\lang1033\fs24 um\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24  clero et populo etc. Amen\plain \f1\lang1033\fs24 , Eidesformel f\u252 \'fcr Schismatiker, nur der Anfang \u252 \'fcbereinstimmend mit \plain \f1\scaps\lang1033\fs24 Friedberg\plain \f1\lang1033\fs24  I, Sp.431;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >C<onsulendum est clericis Romam euntibus causa absolucionis uel dispensacionis}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... in quadam cartula ob mememoriam \plain \f1\lang1033\fs24 [!] \plain \f1\i\lang1033\fs24 quia forte erit ei bonum etc\plain \f1\lang1033\fs24 . Acht Hinweise f\u252 \'fcr Kleriker, die in Rom Dispensen oder Losl\u246 \'f6sungen von Exkommunikationen erlangen wollen. Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augsburg, UB, Cod. II.1.2}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u176 \'b0}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  143 (F\u252 \'fcssen, St. Mang, sp\u228 \'e4tes 14. Jh.), 123}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 ra}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Hilg, \plain \f1\lang1033\fs24 Augsburg I/2, S. 182, sowie in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Uppsala, UB, C 618 (Konstanz, 15. Jh.), 208}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 v}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Andersson-Schmitt/Hedlund\plain \f1\lang1033\fs24 , Uppsala VI, S. 132, in beiden Hss. im Kontext von Bu\u223 \'dfbestimmungen. 135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Rest der Seite leer.}

