\pard\fi0\li0\qc\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 I
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Bl. 1-378  \u183 \'b7  31 VI\plain \f1\super\lang1033\fs20 372\plain \f1\lang1033\fs20  + III\plain \f1\super\lang1033\fs20 378\plain \f1\lang1033\fs20 ; Lagenz\u228 \'e4hlung und Reklamanten, meist beschnitten, s. o.  \u183 \'b7  Schriftraum 13,5 x 9  \u183 \'b7  1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -376\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 378\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  2 Spalten; 377\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  4 Spalten; 377\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -378\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  5 Spalten  \u183 \'b7  1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -376\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  57-61 Zeilen  \u183 \'b7  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Textualis}}\plain \f1\lang1033\fs20  in sehr kleinem Schriftgrad (Perlschrift) von 2 H\u228 \'e4nden, 13. Jh., 2. H\u228 \'e4lfte: 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -376\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  H 1, 377\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -378\plain \f1\super\lang1033\fs20 re\plain \f1\lang1033\fs20  H 2, \u220 \'dcberschriften von sp\u228 \'e4terer Hand (dabei mitunter weniger Platz ben\u246 \'f6tigt als urspr\u252 \'fcnglich vorgesehen und z. T. mit Zeilenf\u252 \'fcllseln ausgef\u252 \'fcllt, z. B. 190\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 , 249\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 , 251\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 ), selten Repr\u228 \'e4sentanten der \u220 \'dcberschriften erhalten (z. B. 221\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 ); 377\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -378\plain \f1\super\lang1033\fs20 re\plain \f1\lang1033\fs20  \u220 \'dcberschriften in hellerer Tinte; 378\plain \f1\super\lang1033\fs20 va-vb\plain \f1\lang1033\fs20  wohl Nachtrag (13. Jh., 2. H\u228 \'e4lfte?), aber ebenfalls (von Nachtragshand?) rubriziert; zahlreiche Korrekturen auf Rasur in dunklerer Tinte sowie marginale Korrekturen von mehreren wenig j\u252 \'fcngeren H\u228 \'e4nden (z. T. beschnitten), z. T. fehlende Passagen am Rand nachgetragen (z. B. 170\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 , 240\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 , 280\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 , 305\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 ) bzw. fehlerhafte Textstellen mit Pergament \u252 \'fcberklebt und erg\u228 \'e4nzt (vgl. 109\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 )  \u183 \'b7  rubriziert  \u183 \'b7  Seitentitel, Kapitelz\u228 \'e4hlung am Rand und 3- bis 6zeilige Abschnittsinitialen (auch am Anfang der Prologe) abwechselnd in Rot und Blau mit Fleuronn\u233 \'e9st\u228 \'e4ben in der Gegenfarbe; Fadenranken und Knospen mit Kern, dazwischen oft langgestreckte V\u246 \'f6gel, s. 4\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 , 6\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  u. \u246 \'f6.  \u183 \'b7  hochwertiger Buchschmuck, vgl. \plain \f1\scaps\lang1033\fs20 Kratzsch,\plain \f1\lang1033\fs20  Alte Hss., S. 13-15 und Schwarzwei\u223 \'dfabb. 5 (S. 17: 3\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) und 6 (S. 18: 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 ): am Anfang der biblischen B\u252 \'fccher und einzelner Psalmen 87 9- bis 26zeilige Initialen in Blau auf rotem Hintergrund bzw. in Rot auf blauem Hintergrund; Deckfarben (Rot, Weinrot, Blau, Altrosa, Grau, Gr\u252 \'fcn, Gelb, Inkarnat und Wei\u223 \'df; wenig Gold); Schmuck\-initialen mit Flechtornamenten aus vegetabilischen Motiven und Akanthusbl\u228 \'e4ttern, darin fig\u252 \'fcrliche Motive: Tiere (V\u246 \'f6gel, Fische, Hase, Fuchs, Hund), Fabelwesen (Drachen, z. T. mit Menschengesicht) und Menschenk\u246 \'f6pfe, Ausl\u228 \'e4ufer der Initialen mitunter gehalten von Drachen oder Menschen (z. B. 190\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 , 367\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 , 370\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 , 371\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 )  \u183 \'b7  hervorzuheben historisierte Initialen: [Altes Testament:] 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  12zeilige F-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hieronymus in Franziskanerhabit als Schreiber }}\plain \f1\lang1033\fs20 , s. o. Geschichte); 29\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  9zeilige U-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gottvater mit Nimbus und Schriftrolle in der Hand, die vor ihm kniende, anbetende Gestalt [Mose?] segnend}}\plain \f1\lang1033\fs20 ); 37\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  7zeilige L-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gottvater mit Nimbus und Schriftrolle in der Hand, die vor ihm sitzende, anbetende Gestalt vor bergigem Hintergrund [Mose?] segnend}}\plain \f1\lang1033\fs20 ); 50\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  9zeilige H-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Mose vor dem Volk Israel}}\plain \f1\lang1033\fs20 ); 61\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  9zeilige E-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gottvater und Josua}}\plain \f1\lang1033\fs20 ); 98\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  10zeilige E-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 K\u246 \'f6nig David}}\plain \f1\lang1033\fs20 ); 128\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  10zeilige C-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 K\u246 \'f6nig Salomo}}\plain \f1\lang1033\fs20 ); 147\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  9zeilige E-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Iosias beim Opfer eines Lammes}}\plain \f1\lang1033\fs20 ); 152\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  12zeilige T-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 ein braungekleideter Mann tr\u228 \'e4gt einen rotgewandeten mit gefesselten H\u228 \'e4nden auf der Schulter - Verschleppung Tobits?}}\plain \f1\lang1033\fs20 ); 159\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  25zeilige I-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[11]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 K\u246 \'f6nigin [Esther?], stehend auf Vogelgestalt mit Raubtierkopf}}\plain \f1\lang1033\fs20 ); 163\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  10zeilige U-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[12]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 K\u246 \'f6nig}}\plain \f1\lang1033\fs20 ); Psalterinitialen, s. u.; 190\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  10zeilige O-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[13]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 K\u246 \'f6nig Salomo}}\plain \f1\lang1033\fs20 ); 198\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  10-zeilige O-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[14]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gottesmutter mit Kind}}\plain \f1\lang1033\fs20 ); 204\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  9zeilige P-Initiale (K\u246 \'f6nig); 217\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  10zeilige U-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[15]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Prophet Jesaja mit Schriftrolle}}\plain \f1\lang1033\fs20 ); 231\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  9zeilige U-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[16]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Prophet Jeremia mit Schriftrolle}}\plain \f1\lang1033\fs20 ); 280\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  und 281\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  jeweils 9zeilige O-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[18]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Mann, der auf der Schulter einen Sack tr\u228 \'e4gt}}\plain \f1\lang1033\fs20 ); 282\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  15zeilige I-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[19]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Prophet: Agg\u228 \'e4us?}}\plain \f1\lang1033\fs20 ); 283\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  16zeilige I-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[19]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Prophet: Zacharias?}}\plain \f1\lang1033\fs20 ), Initiale nachtr\u228 \'e4glich mit blauer Tinte verl\u228 \'e4ngert; [Neues Testament:] 303\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  9zeilige L-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[20]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 segnender Christus}}\plain \f1\lang1033\fs20 ), 313\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  19-zeilige I-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[21]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Evangelist: Marcus?}}\plain \f1\lang1033\fs20 ), 329\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  15zeilige I-Initiale ({\field{\*\fldinst HYPERLINK "hida://5500[22]/?u"}{\fldrslt \plain \f1\lang10