\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Einband: {\field{\*\fldinst HYPERLINK "hida://5260[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Holzdeckel, mit dunklem Kalbsleder \u252 \'fcberzogen}}\plain \f1\lang1033\fs20 , mit Streicheisenlinien, das Leder br\u252 \'fcchig, {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 nach 1472}}\plain \f1\lang1033\fs20  und vor dem Eintrag im Bibliothekskatalog (um 1475); der Schlie\u223 \'dfenriemen und das Schlie\u223 \'dfen\-lager auf dem VD fehlen; auf dem VD Spuren eines abgel\u246 \'f6sten Titelschildes, ca. 4,2 x 11,5; der Einband wurde nach der Ausl\u246 \'f6sung der Inkunabel im 19. Jh. angepa\u223 \'dft, dabei R\u252 \'fccken mit hellerem Leder erneuert und neues Vorsatz hinten eingef\u252 \'fcgt, auf dem R\u252 \'fccken Titel- und Signaturschild der Weimarer Bibliothek.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset2 Symbol;}{\f3\fnil\fcharset0 Courier;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

