\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Anonymus Cisterciensis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Compendium de statu religiosorum moderni temporis (Tractatus contra proprietarios)}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 U\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 enerabilissimo in Christo patri ac domino\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 domino Cistercii ceterisque doctoribus et prelatis ordinis nostri Cistercii in sacro concilio generali anno domini 1415 Constancie celebrato congregatis. \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Text:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pro evidenti et necessaria salute animarum querimus, utrum uel quomodo abbates}}\plain \f1\i\lang1033\fs24  uel monachii \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 ac moniales ordinis nostri Cistercii existentes proprietarii uel peculiarii possunt saluari \plain \f1\lang1033\fs24 ... - ... {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Seneca}}\plain \f1\i\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Concordia parue res crescunt}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistulae morales ad Lucilium}}\plain \f1\lang1033\fs24 , ep. 94, pars 46)\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Primum ergo querite regnum dei ... \plain \f1\lang1033\fs24 (Lc 12,32)\plain \f1\i\lang1033\fs24 . \plain \f1\lang1033\fs24 [von sp\u228 \'e4terer Hand, 15. Jh., 2. H\u228 \'e4lfte, nachgetragen:] \plain \f1\i\lang1033\fs24 Terminatur hic compendium religiosorum moderni temporis super dampnabili vicio proprietatis, anno domini Millesimo quadringentesimo decimoquinto in concilio Constanciensi promulgatum.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Teiledition: Acta Concilii Contanciensis, hg. v. H. \plain \f1\scaps\lang1033\fs24 Finke\plain \f1\lang1033\fs24 , Bd. 4, M\u252 \'fcnster 1928 (ND M\u252 \'fcnster 1982), S. 671-676. Zur \u220 \'dcberlieferung vgl. ebd., S. 671. Eine weitere Abschrift des Werkes aus der Erfurter Kartause innerhalb einer Textsammlung zu den Reformkonzilien\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 vgl\plain \f1\scaps\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 T\u252 \'fcbingen, UB, Hs. }}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mc 282-1, 241}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\scaps\lang1033\fs24 , \plain \f1\lang1033\fs24 vgl.\plain \f1\scaps\lang1033\fs24  Brinkhus/Mentzel-Reuters\plain \f1\lang1033\fs24 , UB T\u252 \'fcbingen 1.2, S. 170 und 554. Zum Text: \plain \f1\scaps\lang1033\fs24 Egan,\plain \f1\lang1033\fs24  S. 144*f. Zum Thema vgl. B. D. \plain \f1\scaps\lang1033\fs24 Haage\plain \f1\lang1033\fs24  / Chr. \plain \f1\scaps\lang1033\fs24 St\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 llinger-L\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 ser\plain \f1\lang1033\fs24 , Art. \u8218 \'82Privatbesitz im Ordensleben\rquote , in: \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 VL 7 (1989), Sp. 845-850 mit weiterer Lit.}

