\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Anno domini m\u176 \'b0cccc\u176 \'b0xiv\u176 \'b0 inventi sunt plures heretici in Thuringia, et specialiter in Sangerhusen}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 -\plain \f1\i\lang1033\fs24  ... hominis utriusque sexus arrestavit propter heresim in foliis precedentibus scriptis\plain \f1\lang1033\fs24 . 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Edition: \plain \f1\scaps\lang1033\fs24 Riemeck\plain \f1\lang1033\fs24 , Flagellanten (s. o. 166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), S. 75. Zur Verfolgung der Flagellanten in Sangerhausen vgl. Fr. \plain \f1\scaps\lang1033\fs24 Schmidt\plain \f1\lang1033\fs24 , Geschichte der Stadt Sangerhausen, Bd. 1, Sangerhausen 1906, S. 858-864. Die \plain \f1\i\lang1033\fs24 Articuli hereticorum in Sangerhusen\plain \f1\lang1033\fs24  auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Frankfurt, StUB, Ms. Barth. 72 (Mitteldeutschland, 15. Jh., 1. Viertel), 174}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 -178}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Powitz/Buck\plain \f1\lang1033\fs24 , Frankfurt 3, S. 158 sowie in Fritzlar, DB, Ms. 130, 100\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -101\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 List\plain \f1\lang1033\fs24 , Fritzlar, S. 237.}

