\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >Q<uoniam in multiloquo}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [sic]\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 (Prv 10,19) \plain \f1\i\lang1033\fs24 et pauca sapientibus uerba sufficiunt ...\plain \f1\lang1033\fs24  (S. 141) ... \plain \f1\i\lang1033\fs24 Clarissimus itaque pater noster Odo abbas deo deuotus et\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 gratus hominibus cuius memoria in benedictione est ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... ubi sine iniuria patri filius immolatur.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Offensichtlich auf {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Odo von Cluny}}\plain \f1\lang1033\fs24  bezogener Sermo, vgl. PL 171, Sp. 759, Anm.1. Nicht in BHL sowie den Datenbanken PL, AASS, Cetodoc, \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , MGH nachweisbar.}

