\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 140\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -154\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes de Plauen}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Computus dictus \u8218 \'82Oycreper\rquote }}\plain \f1\lang1033\fs24 . 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (140\plain \f1\super\lang1033\fs24 ra-vb\plain \f1\lang1033\fs24 ) [Prolog:] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Circa inicium huius sciendum ut per philosophum in prohemia physicorum}}\plain \f1\i\lang1033\fs24  ... Incipit \u8218 \'82Oycreper\rquote \plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 de\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Iste liber de cuius subiecto siue thema materiali dictum est \u8230 \'85\plain \f1\lang1033\fs24 ; (141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -154\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [Text:] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [I]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ncipit oycreper }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [dar\u252 \'fcber Glosse: computus] }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 de motu solis et lune}}\plain \f1\lang1033\fs24  \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 dar\u252 \'fcber Glosse:\plain \f1\i\lang1033\fs24  et de inuentione loci solis et lune\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 et maxime iuuenibus et minus tritis aptus \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 dar\u252 \'fcber Glosse:\plain \f1\i\lang1033\fs24  id est utilis\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 in Plawensi opido compositus utilis facilis et planus \plain \f1\lang1033\fs24 ... - \plain \f1\i\lang1033\fs24 ... per inuenta probat sic significatur \plain \f1\lang1033\fs24 (?) \plain \f1\i\lang1033\fs24 et monstrat\plain \f1\lang1033\fs24 ; (154\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Tabula\plain \f1\i\lang1033\fs24 . 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Nicht gedruckt. Vgl. \plain \f1\scaps\lang1033\fs24 Zinner,\plain \f1\lang1033\fs24  Astronomische Hss., Nr. 8466. Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Krakau, Bib. Jagellonica, cod. 551 (Prag, 1388), 112}}\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , vgl. Krakau, Bib. Jagellonica III, S. 340f., sowie {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Prag, NB, X. E. 19, 133}}\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; XIII. C. 17, 145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  und XIII. F. 17, 120\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , vgl. \plain \f3\scaps\lang1024\fs24 Truhl\plain \f3\scaps\lang1024\fs24 \u225 \'e1\u345 \'f8\plain \f1\lang1033\fs24 , Prag II, Nr. 1920, 2292 und 2355 (nach Angabe dieser Hss. war der Verfasser \u8222 \'84rector scholaris in Plavensi oppido\ldblquote ).}

