\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 He beghint de gemeyne bycht. \plain \f1\lang1033\fs24 (1) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 5 Sinne:\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Uan den u synen: Horen, seen, ruken}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (2) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 4 rufende S\u252 \'fcnden:\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Duse sunden ropen in den hemel ouer sele unde liue}}\plain \f1\i\lang1033\fs24 : Woker, lou, dotslach ...\plain \f1\lang1033\fs24 ;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (3) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 7 Werke der Barmherzigkeit:\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit synt de uii werke der barmherticheit: Hemesuken, spisen, lauen}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; (4) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 7 Werke der geistlichen Barmherzigkeit:\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit sint de vii geystlik: Straffen, vergif, bede}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; (5) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 7 Sakramente:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit synt de vii sacramente der hilgen kerche: Ordo, echtsc}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [korr.:-h]}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ap, dope}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (6) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 7 Gaben des heiligen Geistes:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit sind de uii gaue des hilgen gist: Uisheit, verstantnisse, rad}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; (7) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 7 S\u252 \'fcnden wider den heiligen Geist:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit sint de sunden in den hilgen gist: Anuechten de warheit, uermetenheit}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; (8) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 7 Tods\u252 \'fcnden:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit synt de seuen dotliken sunden: Houerdicheit, ghiricheit}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; (9) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 8 Seligkeiten:\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[8].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit sint de viii selicheit: Armod des geystes, ueruolghinge}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; (10) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 9 fremde S\u252 \'fcnden:\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[9].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dit sint de ix uremede sunden: Heysen, raden}}\plain \f1\i\lang1033\fs24  ..