\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (2) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich Johannes van Lair lantpastor zu Lair }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [evtl. Oberlahr, Peterslahr oder Burglahr, s. u.]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  doin kunt und bekennen }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Wort unleserlich]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  dissen briff}}\plain \f1\i\lang1033\fs24  \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 ...\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 dass Henricus Henne syne broder \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 ...\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  yn montberschaff \plain \f1\lang1033\fs24 (Vormundschaft) \plain \f1\i\lang1033\fs24 ufgedragen hait alle forderunge an soilchen guden hee hait in Flammersuelder kirspel zce Daspach \plain \f1\lang1033\fs24 (wohl Flammersfeld im Westerwald, Landkreis Altenkirchen, wenige Kilometer entfernt befinden sich die Orte Dasbach, Oberlahr, Peterslahr, Burglahr) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 ...\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24  Und zoe gezuge der warheit hain ich Johan uan Lair \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 ...\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 segel neden uff spacium dusser scrifft gedruck \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 ...\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24 .
