4nde: 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -110\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 128\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -237\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Hand 1 ({\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 schleifenlose Bastarda}}\plain \f1\lang1033\fs20 ), 110\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -111\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Hand 2 ({\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kursive}}\plain \f1\lang1033\fs20 ), 111\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -127\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 237\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -275\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Hand 3 (schleifenlose Bastarda)  \u183 \'b7  rubriziert  \u183 \'b7  2- bis 3zeilige rote Lombarden  \u183 \'b7  2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  5zeilige Initiale in Rot und Blau mit Aussparornamentik, im Binnenfeld eine vierbl\u228 \'e4ttrige Bl\u252 \'fcte, Fleuronn\u233 \'e9 in Rot, gr\u252 \'fcn laviert, Perlenketten; 67\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  5zeilige blaue Initiale mit Aussparornamentik, Fleuronn\u233 \'e9 in Rot und Gr\u252 \'fcn; 128\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  5zeilige Initiale in Rot und Blau mit Aussparornamentik, Fleuronn\u233 \'e9 in Rot und Gr\u252 \'fcn; 168\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 203\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 241\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  5zeilige Initialen in Rot und Blau mit Aussparornamentik, Fleuronn\u233 \'e9 in Gr\u252 \'fcn, Gelb und Rot, 202\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  3zeilige blaue Initiale mit Fleuronn\u233 \'e9 und Bl\u252 \'fctenranke in Gr\u252 \'fcn, Gelb und Rot, im Binnenfeld Zeichnung: {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kopf eines M\u246 \'f6nchs mit Tonsur}}\plain \f1\lang1033\fs20   \u183 \'b7  Blattweiser.
