\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat17 >Que sunt que promovent ad ingressum religionis< Nota quod [ad] ingressum promouent tria scilicet priuilegia, prerogatiua et mundi pericula}}\plain \f2\i\lang1033\fs24 . Priuilegia sunt \plain \f3\lang1024\fs24 [\plain \f2\lang1033\fs24 gestrichen: \plain \f2\i\lang1033\fs24 duodecim\plain \f3\lang1024\fs24 ]\plain \f2\lang1033\fs24  \plain \f2\i\lang1033\fs24 tredecim ... \plain \f2\lang1033\fs24 - \plain \f2\i\lang1033\fs24 ... falsitas et decepcio regnant in mundo quare etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 Traktat in drei Kapiteln ([De privilegiis]\plain \f2\i\lang1033\fs24 , De prerogatiuis, De periculis mundi\plain \f2\lang1033\fs24 ), unvollst\u228 \'e4ndig, vgl. \plain \f2\scaps\lang1033\fs24 Mitschke,\plain \f2\lang1033\fs24  S. 121.}

