\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 S\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 Tephanus Fliscus de Sontino iuveni peritissimo Johanni Meliorancio ...\plain \f1\lang1033\fs24 ; [Prolog 1:] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum superiora }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [es fehlt: verborum] }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 synonima tibi breviter absoluerem}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; [Prolog 2:] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >Q<uoniam mi studiosissime Johannes quociens a nobis dicendum est}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ; (191\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ... \plain \f1\lang1033\fs24 [Text:] {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sequitur }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (!)}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  sententiarum uariationes conuenientes exordio}}\plain \f1\i\lang1033\fs24 . Deus sit nobis adiumento ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... \plain \f1\lang1033\fs24 (245\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  ... ponam in extremo quod sencio. \plain \f1\lang1033\fs24 (245\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [Conclusio:] \plain \f1\i\lang1033\fs24 Valete. Valebis igitur feliciter mi Johannes et me Stephanum Fliscum ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... dicas \plain \f1\lang1033\fs24 [sonst: ducas] \plain \f1\i\lang1033\fs24 uehementer exopto. Amen. Expliciunt sinonima sententiarum Flisci de Sontino rethoris \plain \f1\lang1033\fs24 [nachtr\u228 \'e4glich eingef\u252 \'fcgt:\plain \f1\i\lang1033\fs24  haut\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 exigui. 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 191\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  marginale Korrektur vom Schreiber.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Drucke: GW Nr. 10000-10009 (lat.-dt. Ausgaben), u. a. Augsburg: Johann B\u228 \'e4mler, um 1479 (?) (= GW 10002, eingesehenes Exemplar: Leipzig, UB, Editt.Vett.s.a.m. 50). Entgegen der gew\u246 \'f6hnlich zweisprachigen \u220 \'dcberlieferung in Hss. und fr\u252 \'fchen Drucken hier nur lateinische Lemmata. Vgl. \plain \f1\scaps\lang1033\fs24 Kristeller,\plain \f1\lang1033\fs24  Iter III, S. 434; \plain \f1\scaps\lang1033\fs24 Polak,\plain \f1\lang1033\fs24  S. 158f. Zur \u220 \'dcberlieferung vgl. \plain \f1\scaps\lang1033\fs24 Bursill-Hall\plain \f1\lang1033\fs24 , Nr. 82.14.2.; 132.33.; 132.38 u. \u246 \'f6. (ohne diese Hs.). Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Erfurt, Dep. Erf. CA 4\u176 \'b0 74 (Mitte 15. Jh.), 1}}\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Schum\plain \f1\lang1033\fs24 , Erfurt, S. 343.}

