\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 [am oberen Rand von sp\u228 \'e4terer Hand: \plain \f1\i\lang1033\fs24 Ysidorus de Summo bono.\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Liber Ysidori Yspalensis episcopi de summo bono. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >S<ummum bonum deus est quia incommutabilis est}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... Inde est quod scriptum est: Et mortuo non fraudes misericordiam. Explicit liber Ysidori de summo bono.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Druck: PL 83, Sp. 537D-738B; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bloomfield, Incipits, Nr. 5854}}\plain \f1\lang1033\fs24 ; \plain \f1\scaps\lang1033\fs24 Dekkers\plain \f1\lang1033\fs24  Nr. 1199.
