\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Bl. 61-85  \u183 \'b7  Wz. Bl. 65/66: Dreiberg (DB 2), sehr \u228 \'e4hnlich \plain \f1\scaps\lang1033\fs20 Piccard\plain \f1\lang1033\fs20 -DB Nr. 151504 (W\u252 \'fcrzburg 1460), dieses Wz. auch in Fasz. III-V, VIII, XI  \u183 \'b7  (VI-1)\plain \f1\super\lang1033\fs20 71\plain \f1\lang1033\fs20  + VII\plain \f1\super\lang1033\fs20 85\plain \f1\lang1033\fs20 ; vor Bl. 61 fehlt ein Bl.; 71\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Reklamant  \u183 \'b7  Schriftraum 16-16,5 x 11  \u183 \'b7  32 Zeilen  \u183 \'b7  {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 gotische Buchschrift}}\plain \f1\lang1033\fs20  des Johannes R\u246 \'f6\u223 \'dfler (H 2), datiert 1459, s. u.; von seiner Hand auch Fasz. XV (datiert 1457); 80\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 84\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 85\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  u.\u246 \'f6. marginale Glossen in winziger Kursive der H 1 (Johannes de Indagine, s. o. Geschichte) sowie Glossen von weiterer zeitnaher Hand  \u183 \'b7  rubriziert  \u183 \'b7  61\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  2zeilige rote Lombarde (Repr\u228 \'e4sentant).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

