\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -145\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes de Indagine}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Soliloquium hominis devoti suos defectus cognoscentis et deflentis}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Soliloquium hominis deuoti suos defectus cognoscentis et deflentis. \plain \f1\lang1033\fs24 [daneben von anderer Hand: \plain \f1\i\lang1033\fs24 fratris Johannis Hag. Carthusiensis \plain \f1\lang1033\fs24 (unleserlich)] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [V]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Erbum michi est ad te o princeps regum terre fili eterni regis}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... - ... \plain \f1\i\lang1033\fs24 ut ad te dominum meum post huius vite misere finem ualeam iocunde te duce peruenire qui cum patre ... \plain \f1\lang1033\fs24 Explicit\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 s. o.\plain \f1\i\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Klapper\plain \f1\lang1033\fs24  II, S. 21, D 20, Nr. 10. Auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fritzlar, DomB, Ms. 31, 358rb-363}}\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  (mit gleichlautendem Explicit), vgl. \plain \f1\scaps\lang1033\fs24 List,\plain \f1\lang1033\fs24  Fritzlar, S. 58f. }

