\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Placeat igitur tibi beatissima trinitas domini obsequium servitutis mee}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 ... et ad te habendum in gloria sine fine hoc feci qui es benedictus deus in secula.\plain \f1\lang1033\fs24  \u196 \'c4hnliches Incipit: Corpus Orationum, CCSL 160 E, S. 248: oratio 4257 (Missa sacerdotis, Oratio post communionem).}

