\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Bl. 338-347  \u183 \'b7  Wz. Bl. 343/344: Dreiberg mit zweikonturiger Stange und Kreuz (DB 5), \u228 \'e4hnlich \plain \f1\scaps\lang1033\fs20 Piccard\plain \f1\lang1033\fs20 -DB, Nr. 151439 (Liebst\u228 \'e4tt 1451)\plain \f3\lang1033\fs20  \plain \f1\lang1033\fs20   \u183 \'b7  (VI-2)\plain \f1\super\lang1033\fs20 347\plain \f1\lang1033\fs20 ; nach Bl. 347 fehlen 2 Bll.  \u183 \'b7  Schriftraum 16,5-17 x 11  \u183 \'b7  31-32 Zeilen  \u183 \'b7  338\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -347\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 got. Buchschrift}}\plain \f1\lang1033\fs20  von H 5 (\u228 \'e4hnlich H 3 in Fasz. VI); um 1451; Nachtrag 347\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20  got. Buchschrift von der Haupthand der Hs. Weimar, HAAB, Q 51 [D 5\plain \f1\super\lang1033\fs20 1\plain \f1\lang1033\fs20 ], 15. Jh., 4. Viertel  \u183 \'b7  338\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -339\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  rubriziert, 344\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  und 345\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Korrekturen in Rot  \u183 \'b7  338\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  2zeilige rote Lombarde.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

