\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Fragm. 1 (Koperteinband)  \u183 \'b7  {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Pergament}}\plain \f1\lang1033\fs20   \u183 \'b7  1 Doppelbl., Blattgr\u246 \'f6\u223 \'dfe 20-21 x 15,5  \u183 \'b7  Schriftraum 16-17 x 12  \u183 \'b7  23 Zeilen  \u183 \'b7  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Textura}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 14. Jh., 2. H\u228 \'e4lfte}}\plain \f1\lang1033\fs20   \u183 \'b7  rubriziert  \u183 \'b7  2zeilige rote Lombarden  \u183 \'b7  \plain \f1\b\lang1033\fs20 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Aelius Donatus}}\plain \f1\b\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Ars minor}}\plain \f1\b\lang1033\fs20 ]\plain \f1\lang1033\fs20 , sp\u228 \'e4tmittelalterlicher Normaltext, Textbestand: 26,58-29,23. Edition: \plain \f1\scaps\lang1033\fs20 Schwenke,\plain \f1\lang1033\fs20  Donat-Type, S. 37-49, hier S. 44f. }

