\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 50\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , 53\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -53\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Chronikalische Nachtr\u228 \'e4ge mehrerer Schreiber, u. a. auf Erfurt und die Erfurter Kartause bezogen}}\plain \f1\lang1033\fs24  (s. o. Geschichte).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (1) (50\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, Ende 14. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  zu Br\u228 \'e4nden und Naturkatastrophen in Erfurt 1374: \plain \f1\i\lang1033\fs24 Anno domini Millesimo CCC lxxiiii in die Felicis in pincis \plain \f1\lang1033\fs24 [14.1.] \plain \f1\i\lang1033\fs24 fuit incensio. Februarii eadem die incepit frigus magnum ... et uenit tanta inundacio aquarum \plain \f1\lang1033\fs24 [eingef\u252 \'fcgt:\plain \f1\i\lang1033\fs24  in Erfordia\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (2) (50\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, Ende 14. / Anfang 15. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  zum Auszug des Erfurter Klerus w\u228 \'e4hrend des Streits um den Mainzer Erzstuhl 1375: \plain \f1\i\lang1033\fs24 Item dominica post Scolastice \plain \f1\lang1033\fs24 [10.2.] \plain \f1\i\lang1033\fs24 lxxv anno capitula ecclesiarum sancte Marie et sancti Severi Erfordensis ab Erfordia ... cum multitudine cleri ... recesserunt\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (3) (50\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, Ende 14. / Anfang 15. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  zum Tod des {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 K\u246 \'f6nigs Johann von B\u246 \'f6hmen}}\plain \f1\lang1033\fs24  (1346) und zur Wahl seines Sohnes {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karl (IV.)}}\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (4) (53\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, 2. H\u228 \'e4lfte 14. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wahldaten deutscher K\u246 \'f6nige}}\plain \f1\lang1033\fs24  von Rudolf von Habsburg (1273) bis Karl IV. (1346);
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (5) (53\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, Ende 14. / Anfang 15. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  Todesdaten der P\u228 \'e4pste {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Urban V}}\plain \f1\lang1033\fs24 . (1370) und {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gregor XI.}}\plain \f1\lang1033\fs24  (1378);
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (6) (53\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Textura in gr\u246 \'f6\u223 \'dferem Schriftgrad, 14. / 15. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  Bau- und Weihedaten der Kirche der Erfurter Kartause: \plain \f1\i\lang1033\fs24 Anno domini Millesimo CCClxxsecundo inchoata fuit structura Claustri Cartusiensis in Erfordia et sequenti anno in Dominica Iudica \plain \f1\lang1033\fs24 [3.4.] \plain \f1\i\lang1033\fs24 fuit consecrata ecclesia eorum\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (7) (53\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, Ende 14. / Anfang 15. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  Erw\u228 \'e4hnung des {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8222 \'84falschen Waldemar\ldblquote }}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Anno domini m\plain \f2\i\lang1024\fs24 \u176 \'b0\plain \f1\i\lang1033\fs24 ccc\plain \f2\i\lang1024\fs24 \u176 \'b0\plain \f1\i\lang1033\fs24 xlviii\plain \f2\i\lang1024\fs24 \u176 \'b0\plain \f1\i\lang1033\fs24  Waldemarius marchio Brandenburgensis reuersus est ...\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (8) (53\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, 14. / 15. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  Zitat aus: {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Eusebii Caesariensis}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chronicon Hieronymi continuatio}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beatus Iheronimus in cronicis que contexit manibus ita commemorans ait: Ab Adam}}\plain \f1\i\lang1033\fs24  usque ad diluvium anni duo milia ...\plain \f1\lang1033\fs24 , Edition: Eusebius Werke, Bd. 7: Hieronymi Chronicon, hg. v. R. \plain \f1\scaps\lang1033\fs24 Helm\plain \f1\lang1033\fs24 , Berlin \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 1984, S. 250, vgl. \plain \f1\scaps\lang1033\fs24 Dekkers\plain \f1\lang1033\fs24 , Nr. 615c;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (9) (53\plain \f1\super\lang1033\fs24 va-vb\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, Ende 14. / Anfang 15. Jh.:\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  Zitat \u252 \'fcber Weihehindernisse. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quidam Romani pontifices decreuerunt ne presbyterorum filii assumentur}}\plain \f1\i\lang1033\fs24  ad aliquam gradum seu ad pontificatum ...\plain \f1\lang1033\fs24 , evtl. Bezug auf {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Innocentius III}}\plain \f1\lang1033\fs24 ., {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Regesta sive epistolae}}\plain \f1\lang1033\fs24 , PL 216, Sp. 914B;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (10) (53\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 Kursive, 15. Jh.\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24 : Verse \u252 \'fcber eine Weissagung vom Untergang Roms: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Fridericus secundus Heinrici imperatoris sexti filius narratur scripsisse }}\plain \f1\i\lang1033\fs24 Innocencio pape iiii\plain \f2\i\lang1024\fs24 \u176 \'b0\plain \f1\i\lang1033\fs24  ut legitur in cronicis Romanorum hos versus: Facta \plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 sonst: Fata\plain \f2\lang1024\fs24 ]\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 monent stelleque docent auiumque uolatus ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ad hos versus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 respondit dominus Innocencius papa iiii\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24  predictus: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Facta }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [sonst: Fata]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  silent stelleque tacent}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Walther}}{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , Carmina, Nr. 6281}}\plain \f1\lang1033\fs24 ; O. \plain \f1\scaps\lang1033\fs24 Holder-Egger\plain \f1\lang1033\fs24 , Italienische Prophetien des 13. Jahrhunderts, in: NA 30 (1905), S. 336-349; Ch. H. \plain \f1\scaps\lang1033\fs24 Haskins\plain \f1\lang1033\fs24 , Latin Literature under Frederick II, in: Speculum 3/2 (April 1928), S. 129-151, hier S. 148.}

