\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -37\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Annotationes in orationem {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 M.T. Ciceronis}}\plain \f1\i\lang1033\fs24  pro {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Q}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [uinto]}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Ligario}}\plain \f1\i\lang1033\fs24  a R\plain \f1\lang1033\fs24 [everendo] \plain \f1\i\lang1033\fs24 D\plain \f1\lang1033\fs24 [omino] \plain \f1\i\lang1033\fs24 M\plain \f1\lang1033\fs24 [agistro] \plain \f1\i\lang1033\fs24 Conrado Bergio Pomerano professore publico in Academia Witteborgensi A\plain \f2\lang1024\fs24 [\plain \f1\lang1033\fs24 nn\plain \f2\lang1024\fs24 ]\plain \f1\i\lang1033\fs24 o\plain \f1\lang1033\fs24  [15]\plain \f1\i\lang1033\fs24 75. 13 Octobris.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f3\lang1024\fs24\chcbpat17 Conrad Bergius}}\plain \f3\lang1024\fs24  aus Kolberg (Ko\u322 \'b3obrzeg, Pol\plain \f1\lang1033\fs24 en) studierte seit Oktober 1566 an der Universit\u228 \'e4t Wittenberg, 1574-78 war er Professor der Rhetorik, 1577/78 Dekan der philosophischen Fakult\u228 \'e4t, 1578 wurde er Rektor des Gymnasiums in Stettin und 1588 Pfarrer der Stettiner Marienkirche; nach seiner R\u252 \'fcckkehr nach Wittenberg promovierte er 1589 zum Doktor der Theologie; \u8224 \'86 13. M\u228 \'e4rz 1592, vgl. \plain \f1\scaps\lang1033\fs24 F\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 rstemann\plain \f1\lang1033\fs24  II, S. 105, \plain \f1\scaps\lang1033\fs24 Kathe\plain \f1\lang1033\fs24 , Philosophische Fakult\u228 \'e4t, S. 152, 467; DBI I, S. 252.}

