\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f3\i\lang1024\fs24 FRATRIS BAPTIST\u280 \'ca CARMELITE MANTVANI TEOLOGI AD ALFONSVM CALABRIE DUCEM POST EXPVLSOS EX ITALIA TVRCOS PANAGIRIC\plain \f1\i\lang1033\fs24 VM \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 CARMEN\plain \f1\lang1033\fs24 .\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >R<egia progenies sceptris Alfonse gerendis}}\plain \f1\i\lang1033\fs24  / \u8230 \'85 - \u8230 \'85 / Dona fide immensum coeli donabit honorem. \plain \f3\i\lang1024\fs24 Finis Bononi\u281 \'ea MccccLxxxi\plain \f1\lang1033\fs24 ; s. o. Geschichte.
